text:
{
  "version": 1,
  "checks": [
    {
      "id": "goal",
      "status": "present",
      "evidence": "“设计一次面向经销商的30分钟需求访谈，了解其实际订货流程、相关人员、使用工具、遇到的问题及需求。”"
    },
    {
      "id": "role",
      "status": "present",
      "evidence": "“你是一名虚构快消企业的产品经理。”"
    },
    {
      "id": "context",
      "status": "present",
      "evidence": "“虚构快消企业”“面向经销商”；“已知企业背景、经销商情况及现有订货流程尚待补充”。"
    },
    {
      "id": "input",
      "status": "present",
      "evidence": "提供了“已选知识摘录”和输入变量“访谈对象：{{访谈对象}}”。"
    },
    {
      "id": "tasks",
      "status": "present",
      "evidence": "列出了访谈目标、问题覆盖范围、时间分配、记录表及待确认事项等设计要求。"
    },
    {
      "id": "constraints",
      "status": "present",
      "evidence": "“总计严格为30分钟，其中最后3分钟用于受访者核对记录”；“不推断或计算 ROI、成本收益”。"
    },
    {
      "id": "output",
      "status": "present",
      "evidence": "指定按“访谈目标、访谈问题、记录表、待确认事项、结构化输出概念”的顺序输出。"
    },
    {
      "id": "fact_inference",
      "status": "present",
      "evidence": "“对于未知环节，以提问而非事实陈述的方式呈现”；“不将访谈问题本身写成已证实的业务事实”。"
    },
    {
      "id": "anti_fabrication",
      "status": "present",
      "evidence": "“缺失信息标注为‘待确认’，不要编造”；“空白内容使用‘待填写’，不要生成虚构回答”。"
    }
  ],
  "improvements": []
}
